            }
            return Named(name = name, points = points)
        }
    }
}

data class Outer(
    val inner: Named,
    val pair: List<Named>,
    val grid: List<List<Point>>,
    val tags: List<Tagged>,
    val names: List<Named>,
    val bigs: List<Big>,
    val deep: Deep,
) {
    fun size(): Int {
        var size = 16
        size += inner.size()
        for (item in pair) {
            size += item.size()
        }
        size += 1 + tags.size * 5
        size += 1
        for (item in names) {
            size += item.size()
        }
        size += 1 + bigs.size * 2
        size += deep.size()
        return size
    }

    fun toBytes(bytes: ByteArray, index: Int): Int {
        val writer = PackedWriter(bytes, index)
        write(writer)
        return writer.index
    }

    internal fun write(writer: PackedWriter) {
        writer.textUint8(inner.name)
        writer.lengthUint8(inner.points.size)
        for (item in inner.points) {
            writer.int16LittleEndian(item.x)
            writer.int16LittleEndian(item.y)
        }
        require(pair.size == 2) { "pair must hold 2 items, not ${pair.size}" }
        for (item in pair) {
            writer.textUint8(item.name)
            writer.lengthUint8(item.points.size)
            for (item1 in item.points) {
                writer.int16LittleEndian(item1.x)
                writer.int16LittleEndian(item1.y)
            }
        }
        require(grid.size == 2) { "grid must hold 2 items, not ${grid.size}" }
        for (item in grid) {
            require(item.size == 2) { "item must hold 2 items, not ${item.size}" }
            for (item1 in item) {
                writer.int16LittleEndian(item1.x)
                writer.int16LittleEndian(item1.y)
            }
        }
        writer.lengthUint8(tags.size)
        for (item in tags) {
            var itemBits0 = 0L
            itemBits0 = itemBits0 or (if (item.on) 1L else 0L)
            itemBits0 = itemBits0 or ((item.mode.value.toLong() and 0x3L) shl 1)
            writer.wordLittleEndian(itemBits0, 1)
            writer.int16LittleEndian(item.at.x)
            writer.int16LittleEndian(item.at.y)
        }
        require(names.size <= 3) { "names holds more than its maximum of 3 items" }
        writer.lengthUint8(names.size)
        for (item in names) {
            writer.textUint8(item.name)
            writer.lengthUint8(item.points.size)
            for (item1 in item.points) {
                writer.int16LittleEndian(item1.x)
                writer.int16LittleEndian(item1.y)
            }
        }
        require(bigs.size <= 2) { "bigs holds more than its maximum of 2 items" }
        writer.lengthUint8(bigs.size)
        for (item in bigs) {
            writer.uint16BigEndian(item.value)
        }
        writer.lengthUint8(deep.level.tags.size)
        for (item in deep.level.tags) {
            var itemBits0 = 0L
            itemBits0 = itemBits0 or (if (item.on) 1L else 0L)
            itemBits0 = itemBits0 or ((item.mode.value.toLong() and 0x3L) shl 1)
            writer.wordLittleEndian(itemBits0, 1)
            writer.int16LittleEndian(item.at.x)
            writer.int16LittleEndian(item.at.y)
        }
        writer.uint8(deep.level.mode.value)
    }

    companion object {
        fun fromBytes(bytes: ByteArray, index: Int): Outer = read(PackedReader(bytes, index))

        internal fun read(reader: PackedReader): Outer {
            val innerName = reader.textUint8()
            val innerPoints = List(reader.lengthUint8()) {
                val innerPointsItemX = reader.int16LittleEndian()
                val innerPointsItemY = reader.int16LittleEndian()
                Point(x = innerPointsItemX, y = innerPointsItemY)
            }
            val inner = Named(name = innerName, points = innerPoints)
            val pair = List(2) {
                val pairItemName = reader.textUint8()
                val pairItemPoints = List(reader.lengthUint8()) {
                    val pairItemPointsItemX = reader.int16LittleEndian()
                    val pairItemPointsItemY = reader.int16LittleEndian()
                    Point(x = pairItemPointsItemX, y = pairItemPointsItemY)
                }
                Named(name = pairItemName, points = pairItemPoints)
            }
            val grid = List(2) { List(2) {
                    val gridItemItemX = reader.int16LittleEndian()
                    val gridItemItemY = reader.int16LittleEndian()
                    Point(x = gridItemItemX, y = gridItemItemY)
                } }
            val tags = List(reader.lengthUint8()) {
                val tagsItemBits0 = reader.wordLittleEndian(1)
                val tagsItemAtX = reader.int16LittleEndian()
                val tagsItemAtY = reader.int16LittleEndian()
                val tagsItemAt = Point(x = tagsItemAtX, y = tagsItemAtY)
                Tagged(
                    on = (tagsItemBits0 and 0x1L) != 0L,
                    mode = Mode.fromValue(((tagsItemBits0 ushr 1) and 0x3L).toUByte()),
                    at = tagsItemAt,
                )
            }
            val names = List(reader.lengthUint8().also { require(it <= 3) { "names holds more than its maximum of 3 items" } }) {
                val namesItemName = reader.textUint8()
                val namesItemPoints = List(reader.lengthUint8()) {
                    val namesItemPointsItemX = reader.int16LittleEndian()
                    val namesItemPointsItemY = reader.int16LittleEndian()
                    Point(x = namesItemPointsItemX, y = namesItemPointsItemY)
                }
                Named(name = namesItemName, points = namesItemPoints)
            }
            val bigs = List(reader.lengthUint8().also { require(it <= 2) { "bigs holds more than its maximum of 2 items" } }) {
                val bigsItemValue = reader.uint16BigEndian()
                Big(value = bigsItemValue)
            }
            val deepLevelTags = List(reader.lengthUint8()) {
                val deepLevelTagsItemBits0 = reader.wordLittleEndian(1)
                val deepLevelTagsItemAtX = reader.int16LittleEndian()
                val deepLevelTagsItemAtY = reader.int16LittleEndian()
                val deepLevelTagsItemAt = Point(x = deepLevelTagsItemAtX, y = deepLevelTagsItemAtY)
                Tagged(
                    on = (deepLevelTagsItemBits0 and 0x1L) != 0L,
                    mode = Mode.fromValue(((deepLevelTagsItemBits0 ushr 1) and 0x3L).toUByte()),
                    at = deepLevelTagsItemAt,
                )
            }
            val deepLevelMode = Mode.fromValue(reader.uint8())
            val deepLevel = Deeper(tags = deepLevelTags, mode = deepLevelMode)
            val deep = Deep(level = deepLevel)
            return Outer(
                inner = inner,
                pair = pair,
                grid = grid,
                tags = tags,
                names = names,
                bigs = bigs,
                deep = deep,
            )
        }
    }
}

