        writer.int32LittleEndian(littleInteger)
        writer.fixedText(code, 6)
    }

    companion object {
        fun fromBytes(bytes: ByteArray, index: Int): Primitives = read(PackedReader(bytes, index))

        internal fun read(reader: PackedReader): Primitives {
