            val small = reader.int8()
            val byte = reader.uint8()
            val short = reader.int16BigEndian()
            val unsignedShort = reader.uint16BigEndian()
            val integer = reader.int32BigEndian()
            val unsignedInteger = reader.uint32BigEndian()
            val long = reader.int64BigEndian()
            val unsignedLong = reader.uint64BigEndian()
            val single = reader.float32BigEndian()
            val double = reader.float64BigEndian()
            val littleInteger = reader.int32LittleEndian()
            val code = reader.fixedText(6)
            return Primitives(
                flag = flag,
                small = small,
                byte = byte,
                short = short,
                unsignedShort = unsignedShort,
                integer = integer,
                unsignedInteger = unsignedInteger,
                long = long,
