data class Record(
    val id: UInt,
    val name: String,
    val severity: Severity,
    val signed: Signed,
    val flags: RecordFlags,
    val labels: List<Label>,
    val values: List<Short>,
    val trailer: UShort,
    val pair: List<String>,
    val nested: List<List<UByte>>,
    val severities: List<Severity>,
    val matrix: List<List<Short>>,
) : Envelope {
    fun size(): Int {
        var size = 18
        size += 2 + utf8Length(name)
        size += 1
        for (item in labels) {
            size += item.size()
        }
        size += 2 + values.size * 2
        for (item in pair) {
            size += 1 + utf8Length(item)
        }
        size += 1
        for (item in nested) {
            size += 4 + item.size * 1
        }
        size += 1 + severities.size * 1
        return size
    }

    fun toBytes(bytes: ByteArray, index: Int): Int {
        val writer = PackedWriter(bytes, index)
        write(writer)
        return writer.index
    }

    override fun encode(prefix: ByteArray): ByteArray {
        val bytes = prefix.copyOf(prefix.size + 1 + size())
        bytes[prefix.size] = 7
        toBytes(bytes, prefix.size + 1)
        return bytes
    }

    internal fun write(writer: PackedWriter) {
        writer.uint32LittleEndian(id)
        writer.textUint16LittleEndian(name)
        writer.uint8(severity.value)
        writer.int16LittleEndian(signed.value)
        var flagsBits0 = 0L
        flagsBits0 = flagsBits0 or (if (flags.active) 1L else 0L)
        flagsBits0 = flagsBits0 or ((flags.level.toLong() and 0x7L) shl 1)
        writer.wordLittleEndian(flagsBits0, 1)
        require(labels.size <= 4) { "labels holds more than its maximum of 4 items" }
        writer.lengthUint8(labels.size)
        for (item in labels) {
            writer.textUint8(item.name)
            writer.float32LittleEndian(item.weight)
        }
        require(values.size <= 4) { "values holds more than its maximum of 4 items" }
        writer.lengthUint16LittleEndian(values.size)
        for (item in values) {
            writer.int16LittleEndian(item)
        }
        writer.uint16BigEndian(trailer)
        require(pair.size == 2) { "pair must hold 2 items, not ${pair.size}" }
        for (item in pair) {
            writer.textUint8(item)
        }
        require(nested.size <= 4) { "nested holds more than its maximum of 4 items" }
        writer.lengthUint8(nested.size)
        for (item in nested) {
            writer.lengthUint32LittleEndian(item.size)
            for (item1 in item) {
                writer.uint8(item1)
            }
        }
        require(severities.size <= 4) { "severities holds more than its maximum of 4 items" }
        writer.lengthUint8(severities.size)
        for (item in severities) {
            writer.uint8(item.value)
        }
        require(matrix.size == 2) { "matrix must hold 2 items, not ${matrix.size}" }
        for (item in matrix) {
            require(item.size == 2) { "item must hold 2 items, not ${item.size}" }
            for (item1 in item) {
                writer.int16LittleEndian(item1)
            }
        }
    }

    companion object {
        fun fromBytes(bytes: ByteArray, index: Int): Record = read(PackedReader(bytes, index))

        internal fun read(reader: PackedReader): Record {
            val id = reader.uint32LittleEndian()
            val name = reader.textUint16LittleEndian()
            val severity = Severity.fromValue(reader.uint8())
            val signed = Signed.fromValue(reader.int16LittleEndian())
            val flagsBits0 = reader.wordLittleEndian(1)
            val flags = RecordFlags(
                active = (flagsBits0 and 0x1L) != 0L,
                level = ((flagsBits0 ushr 1) and 0x7L).toUByte(),
            )
            val labels = List(reader.lengthUint8().also { require(it <= 4) { "labels holds more than its maximum of 4 items" } }) {
                val labelsItemName = reader.textUint8()
                val labelsItemWeight = reader.float32LittleEndian()
                Label(name = labelsItemName, weight = labelsItemWeight)
            }
            val values = List(reader.lengthUint16LittleEndian().also { require(it <= 4) { "values holds more than its maximum of 4 items" } }) { reader.int16LittleEndian() }
            val trailer = reader.uint16BigEndian()
            val pair = List(2) { reader.textUint8() }
            val nested = List(reader.lengthUint8().also { require(it <= 4) { "nested holds more than its maximum of 4 items" } }) { List(reader.lengthUint32LittleEndian()) { reader.uint8() } }
            val severities = List(reader.lengthUint8().also { require(it <= 4) { "severities holds more than its maximum of 4 items" } }) { Severity.fromValue(reader.uint8()) }
            val matrix = List(2) { List(2) { reader.int16LittleEndian() } }
            return Record(
                id = id,
                name = name,
                severity = severity,
                signed = signed,
                flags = flags,
                labels = labels,
                values = values,
                trailer = trailer,
                pair = pair,
                nested = nested,
                severities = severities,
                matrix = matrix,
            )
        }
    }
}

