internal class PackedWriter(private val bytes: ByteArray, var index: Int) {
    fun boolean(value: Boolean) {
        bytes[index] = (if (value) 1 else 0).toByte()
        index += 1
    }

    fun bytesUint16LittleEndian(value: ByteArray) {
        val length = value.size
        require(length <= 65535) { "$length bytes do not fit a UShort length prefix" }
        wordLittleEndian(length.toLong(), 2)
        value.copyInto(bytes, index)
        index += length
    }

    fun bytesUint32LittleEndian(value: ByteArray) {
        val length = value.size
        wordLittleEndian(length.toLong(), 4)
        value.copyInto(bytes, index)
        index += length
    }

    fun bytesUint8(value: ByteArray) {
        val length = value.size
        require(length <= 255) { "$length bytes do not fit a UByte length prefix" }
        bytes[index] = length.toByte()
        index += 1
        value.copyInto(bytes, index)
        index += length
    }

    fun fixedText(value: String, length: Int) {
        val encoded = value.encodeToByteArray()
        val count = minOf(encoded.size, length)
        encoded.copyInto(bytes, index, 0, count)
        bytes.fill(0, index + count, index + length)
        index += length
    }

    fun float32BigEndian(value: Float) {
        wordBigEndian(value.toRawBits().toLong(), 4)
    }

    fun float32LittleEndian(value: Float) {
        wordLittleEndian(value.toRawBits().toLong(), 4)
    }

    fun float64BigEndian(value: Double) {
        wordBigEndian(value.toRawBits(), 8)
    }

    fun int16BigEndian(value: Short) {
        wordBigEndian(value.toLong(), 2)
    }

    fun int16LittleEndian(value: Short) {
        wordLittleEndian(value.toLong(), 2)
    }

    fun int32BigEndian(value: Int) {
        wordBigEndian(value.toLong(), 4)
    }

    fun int32LittleEndian(value: Int) {
        wordLittleEndian(value.toLong(), 4)
    }

    fun int64BigEndian(value: Long) {
        wordBigEndian(value, 8)
    }

    fun int8(value: Byte) {
        bytes[index] = value
        index += 1
    }

    fun lengthUint16LittleEndian(length: Int) {
        require(length <= 65535) { "$length items do not fit a UShort length prefix" }
        wordLittleEndian(length.toLong(), 2)
    }

    fun lengthUint32LittleEndian(length: Int) {
        wordLittleEndian(length.toLong(), 4)
    }

    fun lengthUint8(length: Int) {
        require(length <= 255) { "$length items do not fit a UByte length prefix" }
        bytes[index] = length.toByte()
        index += 1
    }

    fun textUint16LittleEndian(value: String) {
        val encoded = value.encodeToByteArray()
        val length = encoded.size
        require(length <= 65535) { "$length bytes do not fit a UShort length prefix" }
        wordLittleEndian(length.toLong(), 2)
        encoded.copyInto(bytes, index)
        index += length
    }

    fun textUint8(value: String) {
        val encoded = value.encodeToByteArray()
        val length = encoded.size
        require(length <= 255) { "$length bytes do not fit a UByte length prefix" }
        bytes[index] = length.toByte()
        index += 1
        encoded.copyInto(bytes, index)
        index += length
    }

    fun uint16BigEndian(value: UShort) {
        wordBigEndian(value.toLong(), 2)
    }

    fun uint16LittleEndian(value: UShort) {
        wordLittleEndian(value.toLong(), 2)
    }

    fun uint32BigEndian(value: UInt) {
        wordBigEndian(value.toLong(), 4)
    }

    fun uint32LittleEndian(value: UInt) {
        wordLittleEndian(value.toLong(), 4)
    }

    fun uint64BigEndian(value: ULong) {
        wordBigEndian(value.toLong(), 8)
    }

    fun uint8(value: UByte) {
        bytes[index] = value.toByte()
        index += 1
    }

    fun wordBigEndian(value: Long, size: Int) {
        for (byte in 0 until size) {
            bytes[index + size - 1 - byte] = (value ushr (8 * byte)).toByte()
        }
        index += size
    }

    fun wordLittleEndian(value: Long, size: Int) {
        for (byte in 0 until size) {
            bytes[index + byte] = (value ushr (8 * byte)).toByte()
        }
        index += size
    }
}

internal class PackedReader(private val bytes: ByteArray, var index: Int) {
    fun boolean(): Boolean {
        return bytes[index++] != 0.toByte()
    }

    fun bytesUint16LittleEndian(): ByteArray {
        val length = wordLittleEndian(2).toInt()
        val value = bytes.copyOfRange(index, index + length)
        index += length
        return value
    }

    fun bytesUint32LittleEndian(): ByteArray {
        val length = wordLittleEndian(4).toInt()
        val value = bytes.copyOfRange(index, index + length)
        index += length
        return value
    }

    fun bytesUint8(): ByteArray {
        val length = bytes[index++].toInt() and 0xFF
        val value = bytes.copyOfRange(index, index + length)
        index += length
        return value
    }

    fun fixedText(length: Int): String {
        var end = index + length
        while (end > index && bytes[end - 1] == 0.toByte()) end--
        val value = bytes.decodeToString(index, end)
        index += length
        return value
    }

    fun float32BigEndian(): Float {
        return Float.fromBits(wordBigEndian(4).toInt())
    }

    fun float32LittleEndian(): Float {
        return Float.fromBits(wordLittleEndian(4).toInt())
    }

    fun float64BigEndian(): Double {
        return Double.fromBits(wordBigEndian(8))
    }

    fun int16BigEndian(): Short {
        return wordBigEndian(2).toShort()
    }

    fun int16LittleEndian(): Short {
        return wordLittleEndian(2).toShort()
    }

    fun int32BigEndian(): Int {
        return wordBigEndian(4).toInt()
    }

    fun int32LittleEndian(): Int {
        return wordLittleEndian(4).toInt()
    }

    fun int64BigEndian(): Long {
        return wordBigEndian(8)
    }

    fun int8(): Byte {
        return bytes[index++]
    }

    fun lengthUint16LittleEndian(): Int {
        return wordLittleEndian(2).toInt()
    }

    fun lengthUint32LittleEndian(): Int {
        return wordLittleEndian(4).toInt()
    }

    fun lengthUint8(): Int {
        return bytes[index++].toInt() and 0xFF
    }

    fun textUint16LittleEndian(): String {
        val length = wordLittleEndian(2).toInt()
        val value = bytes.decodeToString(index, index + length)
        index += length
        return value
    }

    fun textUint8(): String {
        val length = bytes[index++].toInt() and 0xFF
        val value = bytes.decodeToString(index, index + length)
        index += length
        return value
    }

    fun uint16BigEndian(): UShort {
        return wordBigEndian(2).toUShort()
    }

    fun uint16LittleEndian(): UShort {
        return wordLittleEndian(2).toUShort()
    }

    fun uint32BigEndian(): UInt {
        return wordBigEndian(4).toUInt()
    }

    fun uint32LittleEndian(): UInt {
        return wordLittleEndian(4).toUInt()
    }

    fun uint64BigEndian(): ULong {
        return wordBigEndian(8).toULong()
    }

    fun uint8(): UByte {
        return bytes[index++].toUByte()
    }

    fun wordBigEndian(size: Int): Long {
        var value = 0L
        for (byte in 0 until size) {
            value = value or ((bytes[index + size - 1 - byte].toLong() and 0xFF) shl (8 * byte))
        }
        index += size
        return value
    }

    fun wordLittleEndian(size: Int): Long {
        var value = 0L
        for (byte in 0 until size) {
            value = value or ((bytes[index + byte].toLong() and 0xFF) shl (8 * byte))
        }
        index += size
        return value
    }
}

private fun utf8Length(value: String): Int {
    var length = 0
    var index = 0
    while (index < value.length) {
        val character = value[index]
        length += when {
            character.code < 0x80 -> 1
            character.code < 0x800 -> 2
            character.isHighSurrogate() && index + 1 < value.length && value[index + 1].isLowSurrogate() -> {
                index++
                4
            }
            else -> 3
        }
        index++
    }
    return length
}
